import{_ as e,o as a,c as r,a2 as o}from"./chunks/framework.XXezeKOl.js";const h=JSON.parse('{"title":"记忆的分类","description":"从认知科学借来的几种记忆类型，如何映射到 Agent 的工程实现上。","frontmatter":{"title":"记忆的分类","description":"从认知科学借来的几种记忆类型，如何映射到 Agent 的工程实现上。"},"headers":[],"relativePath":"guide/08-memory/memory-types.md","filePath":"guide/08-memory/memory-types.md","lastUpdated":null}'),s={name:"guide/08-memory/memory-types.md"};function n(i,t,l,d,u,p){return a(),r("div",null,[...t[0]||(t[0]=[o(`<h1 id="记忆的分类" tabindex="-1">记忆的分类 <a class="header-anchor" href="#记忆的分类" aria-label="Permalink to &quot;记忆的分类&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">学习目标</p><ul><li>理解大模型本身&quot;没有记忆&quot;，Agent 的记忆全部是工程手段拼出来的</li><li>掌握短期记忆、长期记忆，以及语义、情景、程序三类长期记忆的区别</li><li>能把一个具体业务需求映射到合适的记忆类型和存储方式</li><li>了解记忆系统设计时要回答的几个关键问题</li></ul></div><h2 id="模型本身是无状态的" tabindex="-1">模型本身是无状态的 <a class="header-anchor" href="#模型本身是无状态的" aria-label="Permalink to &quot;模型本身是无状态的&quot;">​</a></h2><p>先澄清一个最常见的误解：大模型 API 是<strong>无状态</strong>的。每一次 <code>chat.completions.create</code> 调用，模型只能看到你这次请求里传进去的 <code>messages</code>。你觉得 ChatGPT &quot;记得&quot;上一句话，是因为客户端把整段历史又发了一遍。</p><p>所以，Agent 的&quot;记忆&quot;本质上只有一件事：<strong>在合适的时机，把合适的信息放进上下文窗口</strong>。区别只在于信息从哪来、存在哪、怎么挑。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>            ┌────────────── 上下文窗口（每次请求重新组装）──────────────┐</span></span>
<span class="line"><span>            │ system prompt │ 用户画像 │ 检索到的记忆 │ 最近 N 轮对话 │ 本轮输入 │</span></span>
<span class="line"><span>            └───────▲───────────▲────────────▲─────────────▲──────────┘</span></span>
<span class="line"><span>                    │           │            │             │</span></span>
<span class="line"><span>               提示词模板   结构化存储     向量 / 全文检索    会话存储</span></span>
<span class="line"><span>                          (DB / KV)      (长期记忆库)     (内存 / Redis)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>模型的参数里当然也存着大量&quot;知识&quot;（参数记忆，Parametric Memory），但它只能通过训练或微调改变，对应用开发者来说基本是只读的。本模块讨论的都是参数之外、由应用控制的<strong>外部记忆</strong>。</p><h2 id="按时间跨度-短期-vs-长期" tabindex="-1">按时间跨度：短期 vs 长期 <a class="header-anchor" href="#按时间跨度-短期-vs-长期" aria-label="Permalink to &quot;按时间跨度：短期 vs 长期&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>短期记忆（Short-term）</th><th>长期记忆（Long-term）</th></tr></thead><tbody><tr><td>生命周期</td><td>一次会话 / 一个任务内</td><td>跨会话、跨天甚至永久</td></tr><tr><td>典型内容</td><td>对话历史、工具调用结果、当前计划</td><td>用户偏好、事实、历史经验、知识</td></tr><tr><td>存放位置</td><td>进程内存、Redis、会话表</td><td>关系库、KV、向量库、图数据库</td></tr><tr><td>进入上下文的方式</td><td>基本全量（超长时截断或摘要）</td><td>按需检索，只取相关的一小部分</td></tr><tr><td>主要难点</td><td>窗口有限，怎么裁剪</td><td>写什么、怎么检索、如何更新和遗忘</td></tr></tbody></table><p>短期记忆可以类比人的<strong>工作记忆</strong>：容量小、正在处理的东西都在这里。对 Agent 来说，它就是当前的 <code>messages</code> 列表，加上 Agent 循环中的中间状态（例如计划清单、已完成的步骤）。</p><p>长期记忆则需要一个独立的存储，以及一套&quot;写入 → 检索 → 注入上下文&quot;的流程。没有检索这一步，长期记忆就退化成&quot;把所有东西塞进 prompt&quot;，很快就会撞上窗口上限和成本问题。</p><h2 id="长期记忆的三种类型" tabindex="-1">长期记忆的三种类型 <a class="header-anchor" href="#长期记忆的三种类型" aria-label="Permalink to &quot;长期记忆的三种类型&quot;">​</a></h2><p>认知科学把长期记忆分为语义记忆、情景记忆和程序记忆，这个划分在 Agent 领域被广泛借用（例如 LangGraph 文档和 CoALA 论文都采用了类似的划分）。它的价值在于：<strong>不同类型的记忆，适合的存储和检索方式不一样</strong>。</p><h3 id="语义记忆-semantic-memory-事实" tabindex="-1">语义记忆（Semantic Memory）：事实 <a class="header-anchor" href="#语义记忆-semantic-memory-事实" aria-label="Permalink to &quot;语义记忆（Semantic Memory）：事实&quot;">​</a></h3><p>&quot;用户叫张三，是后端工程师，主要用 Go&quot;；&quot;公司报销上限是每月 2000 元&quot;。这类记忆是<strong>与时间无关的事实</strong>，通常有明确的主体和属性。</p><ul><li>适合存储：结构化字段（用户画像表、JSON 文档），或&quot;事实条目&quot;列表</li><li>适合检索：按用户 ID 直接读取；条目多时用向量检索</li><li>关键问题：<strong>冲突和更新</strong>。用户上个月说&quot;在用 Java&quot;，这个月说&quot;转 Go 了&quot;，要覆盖而不是并存</li></ul><h3 id="情景记忆-episodic-memory-经历" tabindex="-1">情景记忆（Episodic Memory）：经历 <a class="header-anchor" href="#情景记忆-episodic-memory-经历" aria-label="Permalink to &quot;情景记忆（Episodic Memory）：经历&quot;">​</a></h3><p>&quot;上周二用户让我排查一个 K8s 的 OOM 问题，最后发现是 JVM 堆参数配置错误&quot;。这类记忆是<strong>带时间和上下文的事件</strong>，像日记。</p><ul><li>适合存储：带时间戳的事件记录、对话摘要，配合向量索引</li><li>适合检索：语义相似度 + 时间衰减（越近越重要）</li><li>典型用途：Few-shot 示例（&quot;上次类似任务是这么做成功的&quot;）、延续之前的话题</li></ul><p>斯坦福的 Generative Agents 论文就是情景记忆的经典案例：每个角色有一条&quot;记忆流&quot;，检索时综合考虑<strong>相关性、时近性、重要性</strong>三个分数。</p><h3 id="程序记忆-procedural-memory-怎么做" tabindex="-1">程序记忆（Procedural Memory）：怎么做 <a class="header-anchor" href="#程序记忆-procedural-memory-怎么做" aria-label="Permalink to &quot;程序记忆（Procedural Memory）：怎么做&quot;">​</a></h3><p>&quot;这个用户喜欢先看结论再看细节&quot;；&quot;部署这个服务时必须先跑数据库迁移&quot;。这类记忆是<strong>行为规则和技能</strong>。</p><ul><li>适合存储：直接写进 system prompt 或规则文件，例如 Claude Code 的 <code>CLAUDE.md</code>、各类 Coding Agent 的项目规则文件</li><li>更新方式：Agent 自我反思后改写指令，或者由人维护</li><li>广义上，模型权重和工具代码也属于程序记忆</li></ul><h2 id="一张映射表" tabindex="-1">一张映射表 <a class="header-anchor" href="#一张映射表" aria-label="Permalink to &quot;一张映射表&quot;">​</a></h2><p>把一个&quot;个人编程助手&quot;的需求拆开，看看每条信息该放在哪：</p><table tabindex="0"><thead><tr><th>需求</th><th>记忆类型</th><th>推荐实现</th></tr></thead><tbody><tr><td>记住这轮对话前面说过的话</td><td>短期</td><td><code>messages</code> 列表，超长后摘要</td></tr><tr><td>记住用户的技术栈和职级</td><td>语义（长期）</td><td>用户画像表，每次请求注入</td></tr><tr><td>记住用户&quot;回答要简短&quot;的偏好</td><td>程序（长期）</td><td>写入 system prompt 的偏好段</td></tr><tr><td>&quot;上次那个报错后来怎么解决的？&quot;</td><td>情景（长期）</td><td>会话摘要 + 向量检索</td></tr><tr><td>公司内部文档、API 手册</td><td>知识（外部）</td><td>RAG 知识库，见 <a href="/guide/09-rag/overview">RAG 全景</a></td></tr></tbody></table><p>注意最后一行：<strong>RAG 知识库和长期记忆在技术上很像</strong>（都会用到向量检索），但定位不同。知识库是&quot;世界知道的东西&quot;，通常由管理员导入、所有用户共享；记忆是&quot;Agent 和某个用户之间发生过的事&quot;，按用户隔离、由对话自动产生。混在一个索引里，常常会出现 A 用户的偏好被检索给 B 用户的事故。</p><h2 id="设计记忆系统要回答的问题" tabindex="-1">设计记忆系统要回答的问题 <a class="header-anchor" href="#设计记忆系统要回答的问题" aria-label="Permalink to &quot;设计记忆系统要回答的问题&quot;">​</a></h2><p>不管选什么方案，下面五个问题都绕不开：</p><ol><li><strong>写什么</strong>：全量对话都存，还是只存提炼后的事实？谁来提炼（规则、LLM）？</li><li><strong>什么时候写</strong>：每轮对话后同步写（&quot;热路径&quot;），还是会话结束后异步写（&quot;后台&quot;）？</li><li><strong>怎么读</strong>：每次都读，还是由 Agent 通过工具主动查询？取多少条？</li><li><strong>怎么更新和遗忘</strong>：新事实与旧事实冲突怎么办？过期的信息要不要删？</li><li><strong>隔离与合规</strong>：记忆按什么维度隔离（用户、租户、项目）？用户能否查看和删除自己的记忆？</li></ol><p>后面三篇会逐一展开：<a href="/guide/08-memory/short-term">短期记忆与会话管理</a> 讲第 1 层，<a href="/guide/08-memory/long-term">长期记忆与用户画像</a> 讲写入与检索，<a href="/guide/08-memory/memory-strategy">记忆读写策略与方案对比</a> 讲各种方案的取舍。</p><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to &quot;常见坑&quot;">​</a></h2><ul><li><strong>以为模型会记住</strong>：API 是无状态的，忘了传历史是新手最常见的 bug，表现为&quot;模型每轮都像第一次见面&quot;。</li><li><strong>一切都塞进向量库</strong>：用户姓名、职级这种确定的结构化事实，直接用数据库字段存取更准确，没必要靠语义相似度去&quot;碰&quot;。</li><li><strong>记忆和知识库混用</strong>：不做用户隔离，就有隐私泄露风险。</li><li><strong>只写不删</strong>：记忆越来越多，过时、矛盾的信息会持续污染上下文，效果反而越来越差。</li><li><strong>把记忆当成可信输入</strong>：记忆内容可能来自用户输入，甚至来自被注入的网页内容，它和用户消息一样不可信，不能让它绕过权限检查。</li></ul><h2 id="小测" tabindex="-1">小测 <a class="header-anchor" href="#小测" aria-label="Permalink to &quot;小测&quot;">​</a></h2><p><strong>1.</strong> 用户说&quot;以后回答都用英文&quot;，这条信息属于哪类记忆？最合适放在哪里？</p><details class="details custom-block"><summary>查看答案</summary><p>属于程序记忆（行为偏好）。最合适的做法是写入用户偏好存储，每次请求时拼进 system prompt，而不是放在向量库里等待检索，因为它每次都需要生效。</p></details><p><strong>2.</strong> 为什么说&quot;把所有历史对话都塞进 prompt&quot;不是一个长期记忆方案？</p><details class="details custom-block"><summary>查看答案</summary><p>上下文窗口有限，历史会持续增长；即使窗口够大，Token 成本和延迟也会线性上涨，而且无关内容过多会降低模型对关键信息的注意力。长期记忆的核心是&quot;存储 + 按需检索&quot;，只把相关的少量信息放进上下文。</p></details><p><strong>3.</strong> 企业知识库和用户长期记忆都用向量检索，为什么建议分开存储？</p><details class="details custom-block"><summary>查看答案</summary><p>两者的来源、共享范围和生命周期不同：知识库由管理员维护、全员共享；记忆由对话产生、按用户隔离、需要支持更新和删除。分开存储便于做权限隔离和独立的更新策略，避免跨用户泄露。</p></details><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="https://arxiv.org/abs/2309.02427" target="_blank" rel="noreferrer">Cognitive Architectures for Language Agents (CoALA)</a>：系统化地讨论了 Agent 的记忆模块划分</li><li><a href="https://arxiv.org/abs/2304.03442" target="_blank" rel="noreferrer">Generative Agents: Interactive Simulacra of Human Behavior</a>：记忆流与检索打分，另见本站 <a href="/papers/generative-agents">论文解读</a></li><li><a href="https://arxiv.org/abs/2310.08560" target="_blank" rel="noreferrer">MemGPT: Towards LLMs as Operating Systems</a>：把上下文窗口类比为内存、外部存储类比为磁盘</li><li>本站：<a href="/guide/07-context-engineering/window-management">上下文窗口管理</a></li></ul>`,42)])])}const c=e(s,[["render",n]]);export{h as __pageData,c as default};
